// Strength Reduction (Multiplication/Division by power of 2)
int n = 42;
int mult_by_8 = n * 8; // Optimized to: n << 3
unsigned int div_by_4 = n / 4; // Optimized to: n >> 2 (for unsigned)

// Common Subexpression Elimination (CSE)
int a = 5;
int term = (a * 10);
int result_1 = term + 1;
int result_2 = term - 1; // (a * 10) computed once

// Optimization target: LEA (Load Effective Address on x86)
